#!/usr/bin/env bash
# Question 4: Deployment ${Q4_NAME}. Generated by Quick Create; variables arrive as environment variables.
set -euo pipefail

kubectl create namespace "${Q4_NS}" --dry-run=client -o yaml | kubectl apply -f - >/dev/null
timeout 60 bash -c "until kubectl -n '${Q4_NS}' get serviceaccount default >/dev/null 2>&1; do sleep 1; done"
kubectl taint node "${Q4_TAINT_NODE}" "dedicated=${Q4_TAINT_TEAM}:NoSchedule" --overwrite
